private TreeNode<T> rotateRight(TreeNode<T> node){
    // If the node is null or has no left child, rotation cannot be performed.
    if (node == null || node.left == null) {
        return node;
    }
    // Perform the rotation.
    TreeNode<T> leftChild = node.left;
    node.left = leftChild.right;   // The right subtree of the left child becomes the left subtree of the original node.
    leftChild.right = node;        // The original node becomes the right child of the new root.
    return leftChild;              // Return the new parent of the original node.
}

