    if (buffer == null) {
        throw new IllegalStateException("Buffer is null");
    }

    // Normalize starting position
    if (pos < 0) {
        pos = 0;
    }
    if (pos >= buffer.length) {
        return -1; // start position beyond buffer
    }

    // Search for the byte value
    for (int i = pos; i < buffer.length; i++) {
