protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive");
    }
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    long currentStart = start;
    while (currentStart <= end) {
        long maxEnd;
        try {
            maxEnd = Math.addExact(currentStart, FETCH_DATA_DURATION - 1);
        } catch (ArithmeticException e) {
            maxEnd = Long.MAX_VALUE;
        }
        long currentEnd = Math.min(maxEnd, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        if (currentEnd == Long.MAX_VALUE) {
            break;
        }
        currentStart = currentEnd + 1;
    }
    return ranges;
}

