static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if(timeBucket <= 0){
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day = (int)(timeBucket % 100);
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("Invalid month in timeBucket");
    }
    if(day < 1 || day > 31){
        throw new IllegalArgumentException("Invalid day in timeBucket");
    }
    try{
        java.time.LocalDate.of(year, month, day);
    }catch(java.time.DateTimeException e){
        throw new IllegalArgumentException("Invalid date in timeBucket", e);
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input CharSequence is null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException(
                "index: " + index + ", len: " + len + ", str.length(): " + str.length());
    }
    long size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // Valid surrogate pair -> 4 bytes
                size += 4;
                i++; // skip low surrogate
            } else {
                // Unpaired high surrogate -> replacement character (3 bytes)
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate -> replacement character (3 bytes)
            size += 3;
        } else {
            // BMP non-ASCII character -> 3 bytes
            size += 3;
        }
        if (size > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("UTF-8 size exceeds Integer.MAX_VALUE");
        }
    }
    return (int) size;
}

