public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate parameters
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative");
    }
    if (byteOffset < 0) {
        throw new IllegalArgumentException("byteOffset must be non‑negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset is beyond the end of the source array");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("byteOffset + byteLength exceeds source array length");
        }
    } else if (byteLength > 0) {
        // byteArrayValue is null but byteLength > 0 – we will insert nullbytes (zeros)
    }

    // Prevent integer overflow when computing new size
    if (size > Integer.MAX_VALUE - byteLength) {
        throw new OutOfMemoryError("ByteVector would exceed maximum array size");
    }
    int newSize = size + byteLength;

    // Ensure internal buffer has enough capacity
    if (data == null) {
        data = new byte[newSize];
    } else if (newSize > data.length) {
        int newCapacity = Math.max(data.length * 2, newSize);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }

    // Copy bytes or insert nullbytes
    if (byteArrayValue == null) {
        // Fill with zeros (nullbytes)
        for (int i = 0; i < byteLength; i++) {
            data[size + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
    }

    size = newSize;
    return this;
}

