public void removeFromTreeEdgeList() {
    try {
        // Remove from source node's tree edge list
        if (prevTreeEdge != null) {
            prevTreeEdge.nextTreeEdge = nextTreeEdge;
        } else if (source != null) {
            source.firstTreeEdge = nextTreeEdge;
        }
        if (nextTreeEdge != null) {
            nextTreeEdge.prevTreeEdge = prevTreeEdge;
        } else if (source != null) {
            source.lastTreeEdge = prevTreeEdge;
        }

        // Remove from target node's tree edge list
        if (prevTreeEdgeSibling != null) {
            prevTreeEdgeSibling.nextTreeEdgeSibling = nextTreeEdgeSibling;
        } else if (target != null) {
            target.firstTreeEdge = nextTreeEdgeSibling;
        }
        if (nextTreeEdgeSibling != null) {
            nextTreeEdgeSibling.prevTreeEdgeSibling = prevTreeEdgeSibling;
        } else if (target != null) {
            target.lastTreeEdge = prevTreeEdgeSibling;
        }

        // Nullify this edge's own pointers
        prevTreeEdge = null;
        nextTreeEdge = null;
        prevTreeEdgeSibling = null;
        nextTreeEdgeSibling = null;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove edge from tree edge list", e);
    }
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        throw new IllegalArgumentException("key and props must not be null");
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    try {
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
        String result = value;
        int maxDepth = 10;
        for (int i = 0; i < maxDepth; i++) {
            java.util.regex.Matcher matcher = pattern.matcher(result);
            StringBuffer sb = new StringBuffer();
            boolean found = false;
            while (matcher.find()) {
                found = true;
                String varName = matcher.group(1);
                String varValue = props.getProperty(varName);
                if (varValue == null) {
                    matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement("${" + varName + "}"));
                } else {
                    matcher.appendReplacement(sb, java.util.regex.Matcher.quoteReplacement(varValue));
                }
            }
            matcher.appendTail(sb);
            result = sb.toString();
            if (!found) {
                break;
            }
        }
        return result;
    } catch (Exception e) {
        throw new RuntimeException("Error during substitution", e);
    }
}

