private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new NullPointerException("Descriptor cannot be null");
    }
    int count = 0;
    try {
        if (descriptor.startsWith("(")) {
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String args = descriptor.substring(1, end);
            int i = 0;
            while (i < args.length()) {
                char c = args.charAt(i);
                if (c == '[') {
                    // array type: consume all '['
                    while (i < args.length() && args.charAt(i) == '[') {
                        i++;
                    }
                    if (i >= args.length()) {
                        throw new IllegalArgumentException("Invalid array type in descriptor");
                    }
                    // next char is type descriptor
                    i++; // consume the type
                    count++;
                } else if (c == 'L') {
                    int semicolon = args.indexOf(';', i);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid object type in descriptor");
                    }
                    i = semicolon + 1;
                    count++;
                } else if ("BCDFIJSZ".indexOf(c) >= 0) {
                    i++;
                    count++;
                } else {
                    throw new IllegalArgumentException("Invalid type descriptor: " + c);
                }
            }
        } else {
            // single type descriptor
            int i = 0;
            char c = descriptor.charAt(0);
            if (c == '[') {
                // array type
                while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                    i++;
                }
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Invalid array type descriptor");
                }
                // next char is type descriptor
                i++;
                count = 1;
            } else if (c == 'L') {
                int semicolon = descriptor.indexOf(';', 1);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid object type descriptor");
                }
                count = 1;
            } else if ("BCDFIJSZ".indexOf(c) >= 0) {
                if (c == 'V') {
                    throw new IllegalArgumentException("Void type cannot be popped");
                }
                count = 1;
            } else {
                throw new IllegalArgumentException("Invalid type descriptor: " + c);
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }

    // pop from stack
    for (int j = 0; j < count; j++) {
        if (outputFrameStack == null) {
            throw new IllegalStateException("Output frame stack not initialized");
        }
        if (outputFrameStack.isEmpty()) {
            throw new IllegalStateException("Stack underflow while popping descriptor: " + descriptor);
        }
        outputFrameStack.pop();
    }
}

@Override
public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b is null");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException("off or len out of bounds");
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int newCapacity = Math.max(buf.length << 1, newCount);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new NullPointerException("Array cannot be null");
    }
    int len = arr.length;
    if (i < 0 || i >= len || j < 0 || j >= len) {
        throw new IndexOutOfBoundsException(
            "Index out of bounds: i=" + i + ", j=" + j + ", length=" + len);
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

