public static String capitalize(String name) {
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    // If the first two characters are both uppercase, return unchanged
    if (len > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise, capitalize the first character
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (first == upperFirst) {
        return name;
    }
    return upperFirst + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Safely handle potential null fields
        if (current.buf == null) {
            current = current.next;
            continue;
        }
        int start = current.start;
        int end = current.end;
        int len = end - start;
        if (len > 0) {
            out.write(current.buf, start, len);
            total += len;
        }
        current = current.next;
    }
    return total;
}

