public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("[");
    try {
        if (this instanceof java.util.Iterable) {
            java.util.Iterator<?> it = ((java.util.Iterable<?>) this).iterator();
            while (it.hasNext()) {
                Object elem = it.next();
                sb.append(String.valueOf(elem));
                if (it.hasNext()) sb.append(", ");
            }
        } else {
            java.lang.reflect.Method sizeMethod = null;
            java.lang.reflect.Method getMethod = null;
            try {
                sizeMethod = this.getClass().getMethod("size");
                getMethod = this.getClass().getMethod("get", int.class);
            } catch (NoSuchMethodException e) {
                // Methods not found
            }
            if (sizeMethod != null && getMethod != null) {
                int sz = 0;
                try {
                    sz = (Integer) sizeMethod.invoke(this);
                } catch (Exception e) {
                    // ignore
                }
                for (int i = 0; i < sz; i++) {
                    Object elem = null;
                    try {
                        elem = getMethod.invoke(this, i);
                    } catch (Exception e) {
                        // ignore
                    }
                    sb.append(String.valueOf(elem));
                    if (i < sz - 1) sb.append(", ");
                }
            } else {
                return super.toString();
            }
        }
    } catch (Exception e) {
        return super.toString();
    }
    sb.append("]");
    return sb.toString();
}

