public String format(final LoggingEvent event){
    if(event == null){
        return "";
    }
    try{
        StringBuilder sb = new StringBuilder();
        // Timestamp
        long ts = event.getTimeStamp();
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sb.append(sdf.format(new java.util.Date(ts)));
        // Level
        sb.append(" [");
        sb.append(event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN");
        sb.append("] [");
        // Thread
        sb.append(event.getThreadName() != null ? event.getThreadName() : "UNKNOWN");
        sb.append("] [");
        // Logger
        sb.append(event.getLoggerName() != null ? event.getLoggerName() : "UNKNOWN");
        sb.append("] - ");
        // Message
        sb.append(String.valueOf(event.getMessage()));
        // Throwable
        if(event.getThrowableInformation() != null){
            java.lang.Throwable t = event.getThrowableInformation().getThrowable();
            if(t != null){
                sb.append(System.lineSeparator());
                sb.append(t.toString());
                for(StackTraceElement ste : t.getStackTrace()){
                    sb.append(System.lineSeparator());
                    sb.append("\tat ").append(ste.toString());
                }
            }
        }
        return sb.toString();
    }catch(Exception e){
        return "";
    }
}

