@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new IllegalArgumentException("Target type must be Character or char");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String of length " + str.length() + " to Character");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < 0 || intVal > 0xFFFF) {
            throw new IllegalArgumentException("Number value out of char range: " + intVal);
        }
        return (char) intVal;
    }
    if (value instanceof Boolean) {
        throw new IllegalArgumentException("Cannot convert Boolean to Character");
    }
    String valStr = value.toString();
    if (valStr.length() == 1) {
        return valStr.charAt(0);
    }
    throw new IllegalArgumentException("Unsupported type for conversion to Character: " + value.getClass().getName());
}

