public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity <= 3) {
        return 3;
    }
    // Ensure starting point is odd
    int start = desiredCapacity;
    if (start % 2 == 0) {
        start++;
    }
    int limit = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        long limitLong = (long)Math.floor(desiredCapacity * 1.11);
        if (limitLong > Integer.MAX_VALUE) {
            limitLong = Integer.MAX_VALUE;
        }
        limit = (int)limitLong;
    }
    // Search within the 11% range first
    for (int n = start; n <= limit; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }
    // If no prime found within the range, continue searching beyond it
    for (int n = limit + 1; n <= Integer.MAX_VALUE; n += 2) {
        if (isPrime(n)) {
            return n;
        }
    }
    // Fallback (should not occur)
    return Integer.MAX_VALUE;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    for (int i = 3; (long)i * i <= n; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

