public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        i++;
        if (i >= len) {
            // Trailing backslash, treat as literal
            sb.append('\\');
            break;
        }
        char next = str.charAt(i);
        switch (next) {
            case 'b':
                sb.append('\b');
                break;
            case 't':
                sb.append('\t');
                break;
            case 'n':
                sb.append('\n');
                break;
            case 'f':
                sb.append('\f');
                break;
            case 'r':
                sb.append('\r');
                break;
            case '\"':
                sb.append('\"');
                break;
            case '\'':
                sb.append('\'');
                break;
            case '\\':
                sb.append('\\');
                break;
            case 'u':
                // Unicode escape: exactly 4 hex digits
                if (i + 4 >= len) {
                    throw new Exception("Invalid Unicode escape sequence at position " + (i - 1));
                }
                String hex = str.substring(i + 1, i + 5);
                for (int h = 0; h < 4; h++) {
                    if (!Character.isDigit(hex.charAt(h)) && !(hex.charAt(h) >= 'a' && hex.charAt(h) <= 'f')
                            && !(hex.charAt(h) >= 'A' && hex.charAt(h) <= 'F')) {
                        throw new Exception("Invalid Unicode escape sequence at position " + (i - 1));
                    }
                }
                int codePoint = Integer.parseInt(hex, 16);
                sb.append((char) codePoint);
                i += 4; // skip the 4 hex digits
                break;
            default:
                // Octal escape: up to 3 octal digits (0-7)
                if (next >= '0' && next <= '7') {
                    int octStart = i;
                    int octEnd = octStart;
                    while (octEnd < len && octEnd - octStart < 3 && str.charAt(octEnd) >= '0' && str.charAt(octEnd) <= '7') {
                        octEnd++;
                    }
                    String oct = str.substring(octStart, octEnd);
                    int octVal = Integer.parseInt(oct, 8);
                    sb.append((char) octVal);
                    i = octEnd - 1; // adjust for loop increment
                } else {
                    // Unknown escape, keep the character as is
                    sb.append(next);
                }
                break;
        }
    }
    return sb.toString();
}

