    try {
        if (root == null) {
            return 0;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            java.util.List<Category> children = current.getChildren();
            if (children == null) {
                continue;
            }
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // Exception handling (e.g., logging) can be added here
    }
    return removed;
}

