private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Validate inputs
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node cannot be null");
    }
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("Direction must be 1 (clockwise) or -1 (counter‑clockwise)");
    }

    try {
        // Create a circulator starting at the start node
        OuterFaceCirculator circ = new OuterFaceCirculator(start);

        // If the start node is the stop node, return immediately
        if (start.equals(stop)) {
            return circ;
        }

        // Keep track of visited nodes to avoid infinite loops
        java.util.Set<Node> visited = new java.util.HashSet<>();
        visited.add(start);

        while (true) {
            // Move to the next or previous node based on the direction
            if (dir > 0) {
                circ = circ.next();
            } else {
                circ = circ.prev();
            }

            // If the circulator became null, break out of the loop
            if (circ == null) {
                break;
            }

            Node current = circ.getNode();
            if (current == null) {
                break;
            }

            // Check if we have reached the stop node
            if (current.equals(stop)) {
                return circ;
            }

            // Check if the current node satisfies the predicate
            if (predicate.test(current)) {
                return circ;
            }

            // If we have already visited this node, we are in a loop
            if (!visited.add(current)) {
                break;
            }
        }

        // If we exit the loop without finding the stop node or a satisfying node,
        // return a circulator positioned at the stop node (if possible)
        return new OuterFaceCirculator(stop);
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception
        throw new RuntimeException("Error during outer face traversal", e);
    }
}

