public static byte convertHexDigit(byte b){
    // Check for numeric digits '0' to '9'
    if (b >= '0' && b <= '9') {
        return (byte)(b - '0');
    }
    // Check for lowercase letters 'a' to 'f'
    if (b >= 'a' && b <= 'f') {
        return (byte)(b - 'a' + 10);
    }
    // Check for uppercase letters 'A' to 'F'
    if (b >= 'A' && b <= 'F') {
        return (byte)(b - 'A' + 10);
    }
    // If the byte does not represent a valid hex digit, throw an exception
    throw new IllegalArgumentException("Invalid hex digit: " + (char)b);
}

private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.isEmpty()) {
        throw new IllegalArgumentException("modelName cannot be null or empty");
    }
    try {
        int[] indices = getShardingKeyIndices(modelName);
        if (indices == null || indices.length == 0) {
            return;
        }
        java.util.Arrays.sort(indices);
        for (int i = 1; i < indices.length; i++) {
            if (indices[i] != indices[i - 1] + 1) {
                throw new IllegalStateException(
                    "Sharding key indices for model " + modelName + " are not continuous: " +
                    java.util.Arrays.toString(indices));
            }
        }
    } catch (IllegalStateException e) {
        throw e;
    } catch (Exception e) {
        throw new IllegalStateException(
            "Failed to check sharding key indices for model " + modelName, e);
    }
}

public byte readByte() throws IOException {
    // Validate that the buffer and input stream are initialized
    if (buffer == null) {
        throw new IllegalStateException("Buffer has not been initialized");
    }
    if (in == null) {
        throw new IllegalStateException("Input stream has not been initialized");
    }
    // Ensure the buffer has a positive length
    if (buffer.length == 0) {
        throw new IllegalStateException("Buffer length must be greater than zero");
    }

    // If the current position has reached the limit, refill the buffer
    if (pos >= limit) {
        int bytesRead = 0;
        // Keep attempting to read until we get data or reach end of stream
        while (bytesRead == 0) {
            bytesRead = in.read(buffer, 0, buffer.length);
            if (bytesRead == -1) {
                throw new IOException("End of stream reached");
            }
            // If read returned 0, try again (handles non-blocking or zero-length reads)
        }
        pos = 0;
        limit = bytesRead;
    }

    // Return the next byte and advance the position
    return buffer[pos++];
}

