protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    // Build adjacency map
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not part of the graph");
        }
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
    }
    // Find start vertex (degree 1 if path, otherwise any vertex for cycle)
    V start = null;
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // cycle: pick any vertex
        start = adjacency.keySet().iterator().next();
    }
    List<E> edgeList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    while (visited.size() < tour.size()) {
        List<E> edges = adjacency.get(current);
        if (edges == null) {
            throw new IllegalArgumentException("Invalid tour: vertex " + current + " has no edges");
        }
        E nextEdge = null;
        for (E e : edges) {
            if (!visited.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("Invalid tour: cannot find next edge from vertex " + current);
        }
        edgeList.add(nextEdge);
        visited.add(nextEdge);
        V source = graph.getEdgeSource(nextEdge);
        V target = graph.getEdgeTarget(nextEdge);
        current = source.equals(current) ? target : source;
    }
    V end = current;
    double weight = 0.0;
    for (E e : edgeList) {
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, start, end, edgeList, weight);
}

