        // In case of unexpected runtime issues, wrap and rethrow as IllegalArgumentException
        throw new IllegalArgumentException("Error concatenating arrays", e);
    }
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate input parameters
    if (bucketsByLabel == null) {
        throw new IllegalArgumentException("bucketsByLabel must not be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel is out of bounds");
    }
    // If the minimum label is already 0, nothing to do
    if (minLabel == 0) {
        return;
    }
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        // Nothing to move
        return;
    }
    // Ensure bucket 0 exists
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }
    // Move vertices from minBucket to zeroBucket
    // Use a copy to avoid ConcurrentModificationException
    for (Integer vertex : new HashSet<>(minBucket)) {
        if (vertex == null) {
            continue; // skip null entries if any
        }
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("Vertex id " + vertex + " is out of bounds for labels list");
        }
        // Update label
        labels.set(vertex, 0);
        // Add to bucket 0
        zeroBucket.add(vertex);
    }
    // Clear the original bucket
    minBucket.clear();
}

