private void pop(final int elements) {
    if (elements <= 0) {
        throw new IllegalArgumentException("Number of elements to pop must be positive");
    }
    if (outputFrameStack == null) {
        throw new IllegalStateException("Output frame stack is not initialized");
    }
    if (outputFrameStack.size() < elements) {
        throw new IllegalStateException("Attempting to pop " + elements + " elements, but only " + outputFrameStack.size() + " available");
    }
    try {
        for (int i = 0; i < elements; i++) {
            outputFrameStack.pop();
        }
    } catch (NoSuchElementException e) {
        throw new IllegalStateException("Failed to pop element from output frame stack", e);
    } catch (Exception e) {
        throw new RuntimeException("Unexpected error while popping elements from output frame stack", e);
    }
}

