void removeSelf() {
    try {
        // Remove this bucket from a doubly linked list structure.
        // Assumes the bucket has 'prev', 'next', and a reference to its parent container.
        if (prev != null) {
            prev.next = next;
        } else if (parent != null) {
            // This bucket is the head of the list; update the parent's head reference.
            parent.head = next;
        }
        if (next != null) {
            next.prev = prev;
        }
        // Clear references to aid garbage collection.
        prev = null;
        next = null;
        parent = null;
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception for visibility.
        throw new RuntimeException("Failed to remove bucket from data structure", e);
    }
}

