private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    try {
        // Adjust the previous node's next reference
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            // node is the head
            head = node.next;
        }

        // Adjust the next node's prev reference
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            // node is the tail
            tail = node.prev;
        }

        // Help GC by severing links
        node.prev = null;
        node.next = null;

        // Decrement size if it is positive
        if (size > 0) {
            size--;
        }

        return true;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, wrap and rethrow
        throw new IllegalStateException("Failed to unlink node", e);
    }
}

