private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    long suffixSum = 0L;
    int[] temp = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        long v = (val == null) ? 0L : val.longValue();
        suffixSum += v;
        temp[i] = (int) suffixSum;
        total += v;
    }
