    if (from < 0 || to >= length || from > to) {
        throw new IllegalArgumentException(
            "Invalid range: from=" + from + ", to=" + to + ", array length=" + length);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("Source list cannot be null");
    }
    // If the source list is the same as this list or empty, nothing to do
    if (list == this || list.size == 0) {
        return;
    }
    // If this list is empty, simply adopt the nodes from the source list
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
        this.size = list.size;
    } else {
        // Link the tail of this list to the head of the source list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        // Update the tail and size of this list
        this.tail = list.tail;
        this.size += list.size;
    }
    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
