    if (prefix == null) {
        return false;
    }
    // If prefix is longer than str, it cannot match
    if (prefix.length() > str.length()) {
        return false;
    }
    try {
        if (ignoreCase) {
            // regionMatches with ignoreCase flag
            return str.regionMatches(true, 0, prefix, 0, prefix.length());
        } else {
            return str.startsWith(prefix);
        }
    } catch (Exception e) {
        // In case of any unexpected runtime exception, return false
        return false;
    }
}

