public ByteVector putInt(final int intValue){
    // Ensure the internal buffer has enough space for 4 more bytes
    if (buf == null) {
        buf = new byte[4];
    } else if (pos + 4 > buf.length) {
        int newCap = Math.max(buf.length * 2, pos + 4);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }
    // Write the int in big-endian order
    buf[pos++] = (byte)(intValue >>> 24);
    buf[pos++] = (byte)(intValue >>> 16);
    buf[pos++] = (byte)(intValue >>> 8);
    buf[pos++] = (byte)intValue;
    return this;
}

