        throw new IllegalArgumentException("Vertices set must not be null");
    }
    for (V v : vertices) {
        if (v == null) {
            throw new IllegalArgumentException("Vertices set must not contain null");
        }
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    // Return an empty list if the input is null or empty
    if (keys == null || keys.isEmpty()){
        return new java.util.ArrayList<Integer>();
    }
    // Prepare the result list with the same size as the input
    java.util.List<Integer> lowerBounds = new java.util.ArrayList<Integer>(keys.size());
    // Iterate over each key to compute its maximum lower bound
    for (int i = 0; i < keys.size(); i++){
        K key = keys.get(i);
        // If the key itself is null, we cannot compute a lower bound
        if (key == null){
            lowerBounds.add(-1);
            continue;
        }
        try{
            // Cast the key to Comparable to allow comparisons
            @SuppressWarnings("unchecked")
            java.lang.Comparable<? super K> compKey = (java.lang.Comparable<? super K>) key;
            K maxLowerKey = null;
            int maxIndex = -1;
            // Scan all other keys to find the maximum key that is <= current key
            for (int j = 0; j < keys.size(); j++){
                if (j == i) continue;
                K other = keys.get(j);
                if (other == null) continue;
                // Ensure the other key is comparable
                @SuppressWarnings("unchecked")
                java.lang.Comparable<? super K> compOther = (java.lang.Comparable<? super K>) other;
                // Check if other <= key
                if (compKey.compareTo(other) >= 0){
                    // Update if this is the first candidate or larger than current max
                    if (maxLowerKey == null || compOther.compareTo(maxLowerKey) > 0){
                        maxLowerKey = other;
                        maxIndex = j;
                    }
                }
            }
            // Store the index of the maximum lower bound key, or -1 if none found
            lowerBounds.add(maxIndex);
        }catch(ClassCastException e){
            // If any key is not comparable, throw an informative exception
            throw new IllegalArgumentException("All keys must implement Comparable", e);
        }catch(Exception e){
            // Catch any unexpected runtime exception and wrap it
            throw new RuntimeException("Error computing lower bounds", e);
        }
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    java.util.List<String> typesToPop = new java.util.ArrayList<>();
    if (descriptor.startsWith("(")) {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String args = descriptor.substring(1, end);
        int i = 0;
        while (i < args.length()) {
            int start = i;
            // consume array brackets
            while (i < args.length() && args.charAt(i) == '[') {
                i++;
            }
            if (i >= args.length()) {
                throw new IllegalArgumentException("Invalid descriptor: incomplete type");
            }
            char c = args.charAt(i);
            if (c == 'L') {
                i++;
                int semicolon = args.indexOf(';', i);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                i = semicolon + 1;
            } else {
                // primitive or void
                i++;
            }
            typesToPop.add(args.substring(start, i));
        }
    } else {
        // type descriptor
        if (descriptor.equals("V")) {
            // void, nothing to pop
            return;
        }
        int i = 0;
        int start = 0;
        while (i < descriptor.length() && descriptor.charAt(i) == '[') {
            i++;
        }
        if (i >= descriptor.length()) {
            throw new IllegalArgumentException("Invalid descriptor: incomplete type");
        }
        char c = descriptor.charAt(i);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
            }
            i = semicolon + 1;
        } else {
            i++;
        }
        if (i != descriptor.length()) {
            throw new IllegalArgumentException("Invalid descriptor: extra characters");
        }
        typesToPop.add(descriptor);
    }

    // Pop from stack
    for (String type : typesToPop) {
        try {
            outputFrameStack.pop();
        } catch (java.util.NoSuchElementException e) {
            throw new IllegalStateException("Stack underflow while popping type: " + type, e);
        }
    }
}

