public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }
    if (path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relativePath must not be empty");
    }
    try {
        boolean absolute = path.startsWith("/");
        // Normalize path components
        java.util.List<String> stack = new java.util.ArrayList<>();
        for (String part : path.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                }
            } else {
                stack.add(part);
            }
        }
        // Apply relative path components
        for (String part : relativePath.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                }
            } else {
                stack.add(part);
            }
        }
        // Build the resulting path
        StringBuilder result = new StringBuilder();
        if (absolute) {
            result.append("/");
        }
        for (int i = 0; i < stack.size(); i++) {
            if (i > 0) {
                result.append("/");
            }
            result.append(stack.get(i));
        }
        // If the result is empty, return "." for relative paths or "/" for absolute paths
        if (result.length() == 0) {
            return absolute ? "/" : ".";
        }
        return result.toString();
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to apply relative path", e);
    }
}

