        // If the threshold is non-positive, consider the metric expired immediately
        if (expiredThreshold <= 0) {
            return true;
        }
        // Avoid negative difference due to future timestamps
        long elapsed = currentTime - timestamp;
        return elapsed > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, default to not expiring to avoid accidental removal
        return false;
    }
}

Edge edgeToNext() {
    try {
        // Retrieve the previously returned node and the next node to be returned
        Node prev = this.prevNode;
        Node next = this.nextNode;

        // Validate that both nodes are available
        if (prev == null || next == null) {
            throw new IllegalStateException("Cannot create edge: previous or next node is null.");
        }

        // Resolve virtual nodes to their real counterparts, if necessary
        if (prev.isVirtual()) {
            Node realPrev = prev.getRealNode();
            if (realPrev == null) {
                throw new IllegalStateException("Previous node is virtual but has no real counterpart.");
            }
            prev = realPrev;
        }

        if (next.isVirtual()) {
            Node realNext = next.getRealNode();
            if (realNext == null) {
                throw new IllegalStateException("Next node is virtual but has no real counterpart.");
            }
            next = realNext;
        }

        // Create and return the edge connecting the two nodes
        return new Edge(prev, next);
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception with context
        throw new RuntimeException("Failed to create edge to next node.", e);
    }
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    // Validate inputs
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();

    // Index must be within bounds and enough space for substring
    if (index < 0 || index > strLen - subLen) {
        return false;
    }

    // Empty substring always matches
    if (subLen == 0) {
        return true;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

