public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            // EOF reached before any tag was read
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return tag;
        }
        shift += 7;
    }
    // If we get here, the varint was too long to be a valid 32‑bit tag
    throw new IOException("Malformed varint while reading tag");
}

