}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    java.util.List<String> lines = java.nio.file.Files.readAllLines(file.toPath());
    boolean filter = timeRanges != null && !timeRanges.isEmpty();
    for (String line : lines) {
        if (line == null || line.trim().isEmpty()) {
            continue;
        }
        try {
            ThreadSnapshot snapshot = null;
            // Try constructor(String)
            try {
                java.lang.reflect.Constructor<?> ctor = ThreadSnapshot.class.getConstructor(String.class);
                snapshot = (ThreadSnapshot) ctor.newInstance(line);
            } catch (NoSuchMethodException e) {
                // Try static parse(String)
                try {
                    java.lang.reflect.Method parseMethod = ThreadSnapshot.class.getMethod("parse", String.class);
                    snapshot = (ThreadSnapshot) parseMethod.invoke(null, line);
                } catch (Exception ex) {
                    // Cannot parse this line
                    continue;
                }
            }
            if (snapshot == null) {
                continue;
            }
            long ts = 0;
            try {
                java.lang.reflect.Method getTs = ThreadSnapshot.class.getMethod("getTimestamp");
                Object tsObj = getTs.invoke(snapshot);
                if (tsObj instanceof Number) {
                    ts = ((Number) tsObj).longValue();
                } else {
                    continue;
                }
            } catch (Exception e) {
                continue;
            }
            boolean inRange = !filter;
            if (filter) {
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    try {
                        java.lang.reflect.Method getStart = ProfileAnalyzeTimeRange.class.getMethod("getStartTime");
                        java.lang.reflect.Method getEnd = ProfileAnalyzeTimeRange.class.getMethod("getEndTime");
                        Object startObj = getStart.invoke(range);
                        Object endObj = getEnd.invoke(range);
                        long start = startObj instanceof Number ? ((Number) startObj).longValue() : Long.MIN_VALUE;
                        long end = endObj instanceof Number ? ((Number) endObj).longValue() : Long.MAX_VALUE;
                        if (ts >= start && ts <= end) {
                            inRange = true;
                            break;
                        }
                    } catch (Exception e) {
                        // ignore this range if methods not found
                    }
                }
            }
            if (inRange) {
                result.add(snapshot);
            }
        } catch (Exception e) {
            // Skip lines that cause any exception
        }
    }
    return result;
}
